window.docContents[151].resolve({"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Two-Loops":{"contents":"\n\n\n\nHere is a pretty inefficient way of adding 3 numbers:X := 0;\nY := 0;\nZ := c;\nwhile X <> a do\n  X := X + 1;\n  Z := Z + 1\nend;\nwhile Y <> b do\n  Y := Y + 1;\n  Z := Z + 1\nend\nShow that it does what it should by completing the\nfollowing decorated program.def twoLoopsDec (a b c : Nat) : Decorated where\n  pre := ({{ True }})\n  body := dcom {\n    ->> {{ sorry }}\n    X := 0 {{ sorry }};\n    Y := 0 {{ sorry }};\n    Z := ~(Aexp.num c) {{\n      sorry\n    }};\n    (while (X ≠ ~(Aexp.num a)) do\n      {{ sorry }}\n      ->> {{ sorry }}\n      X := X + 1 {{\n        sorry\n      }};\n      Z := Z + 1 {{ sorry }}\n    end\n      {{ sorry }}\n    ->> {{ sorry }});\n    while (Y ≠ ~(Aexp.num b)) do\n      {{ sorry }}\n      ->> {{ sorry }}\n      Y := Y + 1 {{ sorry }};\n      Z := Z + 1 {{ sorry }}\n    end\n      {{ sorry }}\n    ->> {{ Z = a + b + c }}\n  }\n\ntheorem two_loops (a b c : Nat) :\n    (twoLoopsDec a b c).OuterTripleValid := by\n  sorry\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II\u0009Finding Loop Invariants","header":"5.3.8. Exercise: Two Loops","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Two-Loops"}});